<template>
	<view class="dropdown-container">
		<!-- 下拉框触发器 -->
		<view 
			class="dropdown-trigger" 
			:class="{ 'dropdown-trigger-active': isOpen }"
			@click="toggleDropdown"
		>
			<text class="dropdown-name">{{ selectedText || placeholder }}</text>
			<text class="dropdown-arrow" :class="{ 'dropdown-arrow-rotated': isOpen }">▼</text>
		</view>
		
		<!-- 下拉选项列表 -->
		<view 
			class="dropdown-options" 
			:class="{ 'dropdown-options-show': isOpen }"
			v-if="isOpen"
		>
			<view 
				v-for="(option, index) in options" 
				:key="index"
				class="dropdown-option"
				:class="{ 'dropdown-option-selected': selectedValue === option.value }"
				@click="selectOption(option)"
			>
				<text class="dropdown-option-text">{{ option.label }}</text>
				<text class="dropdown-option-check" v-if="selectedValue === option.value">✓</text>
			</view>
		</view>
	</view>
</template>

<script>
	export default {
		name: 'Dropdown',
		props: {
			// 选项数据
			options: {
				type: Array,
				required: true,
				default: () => []
			},
			// 占位符文本
			placeholder: {
				type: String,
				default: '请选择'
			},
			// 默认选中的值
			value: {
				type: [String, Number],
				default: ''
			},
			// 高亮颜色
			activeColor: {
				type: String,
				default: '#1890FF'
			},
			// 是否禁用
			disabled: {
				type: Boolean,
				default: false
			}
		},
		data() {
			return {
				isOpen: false,
				selectedValue: this.value,
				selectedText: ''
			}
		},
		watch: {
			value(newVal) {
				this.selectedValue = newVal;
				this.updateSelectedText();
			},
			options: {
				handler() {
					this.updateSelectedText();
				},
				immediate: true
			}
		},
		methods: {
			// 切换下拉框状态
			toggleDropdown() {
				if (this.disabled) return;
				this.isOpen = !this.isOpen;
			},
			
			// 选择选项
			selectOption(option) {
				this.selectedValue = option.value;
				this.selectedText = option.label;
				this.isOpen = false;
				
				// 触发父组件回调
				this.$emit('change', {
					value: option.value,
					label: option.label,
					index: this.options.findIndex(item => item.value === option.value)
				});
			},
			
			// 更新选中文本
			updateSelectedText() {
				const selectedOption = this.options.find(option => option.value === this.selectedValue);
				this.selectedText = selectedOption ? selectedOption.label : '';
			}
		}
	}
</script>

<style scoped>
	.dropdown-container {
		position: relative;
		width: auto;
		flex: 1;
		display: flex;
		justify-content: center;
	}
	
	.dropdown-trigger {
		display: flex;
		align-items: center;
		justify-content: center;
		padding: 16rpx 0;
		background-color: transparent;
		border: none;
		font-size: 28rpx;
		color: #333333;
		transition: all 0.3s ease;
		box-sizing: border-box;
		min-height: auto;
		cursor: pointer;
	}
	
	.dropdown-trigger-active {
		color: #1890FF;
	}
	
	.dropdown-name {
		color: #333333;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
		margin-right: 8rpx;
	}
	
	.dropdown-arrow {
		font-size: 20rpx;
		color: #cccccc;
		transition: transform 0.3s ease;
		flex-shrink: 0;
	}
	
	.dropdown-arrow-rotated {
		transform: rotate(180deg);
		color: #1890FF;
	}
	
	.dropdown-options {
		position: absolute;
		top: 100%;
		left: 50%;
		transform: translateX(-50%);
		background-color: #ffffff;
		border: 1rpx solid #e8e8e8;
		border-radius: 8rpx;
		box-shadow: 0 4rpx 12rpx rgba(0, 0, 0, 0.15);
		z-index: 1000;
		overflow: hidden;
		animation: dropdownSlideDown 0.3s ease-out;
		min-width: 200rpx;
	}
	
	.dropdown-options-show {
		animation: dropdownSlideDown 0.3s ease-out;
	}
	
	.dropdown-option {
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding: 20rpx 24rpx;
		font-size: 28rpx;
		color: #333333;
		background-color: #ffffff;
		transition: background-color 0.2s ease;
		border-bottom: 1rpx solid #f5f5f5;
	}
	
	.dropdown-option:last-child {
		border-bottom: none;
	}
	
	.dropdown-option:hover {
		background-color: #f8f9fa;
	}
	
	.dropdown-option-selected {
		background-color: #e6f7ff;
		color: #1890FF;
	}
	
	.dropdown-option-text {
		flex: 1;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
	
	.dropdown-option-check {
		font-size: 24rpx;
		color: #1890FF;
		font-weight: bold;
		margin-left: 16rpx;
		flex-shrink: 0;
	}
	
	/* 下拉动画 */
	@keyframes dropdownSlideDown {
		from {
			opacity: 0;
			transform: translateY(-20rpx);
			max-height: 0;
		}
		to {
			opacity: 1;
			transform: translateY(0);
			max-height: 400rpx;
		}
	}
	
	/* 禁用状态 */
	.dropdown-trigger[disabled] {
		background-color: #f5f5f5;
		color: #999999;
		cursor: not-allowed;
	}
	
	.dropdown-trigger[disabled] .dropdown-arrow {
		color: #cccccc;
	}
</style>
